// Filter for urgent zones: fusion_score >= 75 and high/medium confidence
const scores = $input.first().json;
const list = Array.isArray(scores) ? scores : [scores];

const highPriority = list.filter(item => {
  return Number(item.fusion_score) >= 75 && (item.confidence === 'high' || item.confidence === 'medium');
});

return highPriority.map(item => ({
  json: {
    ...item,
    urgency_tag: Number(item.fusion_score) >= 85 ? '🔴 CRITICAL' : '🟠 HIGH PRIORITY',
    alert_text: `${Number(item.fusion_score) >= 85 ? '🔴 CRITICAL' : '🟠 HIGH PRIORITY'}: WATER LEAK DISPATCH\n` +
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n` +
      `📍 Zone: ${item.zone_id} (${item.name})\n` +
      `🏆 City Rank: #${item.rank} | Fusion Score: ${Number(item.fusion_score).toFixed(1)}/100\n` +
      `🎯 Confidence: ${String(item.confidence).toUpperCase()} (${item.signals_used}/3 signals agree)\n\n` +
      `📊 Sub-Signals:\n` +
      `  • 🛰️ Satellite: ${item.satellite_score != null ? item.satellite_score.toFixed(1) + '/100' : 'N/A'}\n` +
      `  • 💧 Billing NRW: ${item.billing_score != null ? item.billing_score.toFixed(1) + '/100' : 'N/A'}\n` +
      `  • 📱 Citizen Reports: ${item.citizen_score != null ? item.citizen_score.toFixed(1) + '/100' : 'N/A'}\n\n` +
      `💡 Summary: "${item.explanation}"\n\n` +
      `🛠️ Action: Inspect pipeline corridor in ${item.zone_id}.`
  }
}));
